package safemap

import (
	"sync"
	"testing"
)

type SafeMap[K comparable, V any] struct {
	mu sync.RWMutex
	m  map[K]V
}

func NewSafeMap[K comparable, V any]() *SafeMap[K, V] {
	return &SafeMap[K, V]{
		m: make(map[K]V),
	}
}

func (s *SafeMap[K, V]) Get(key K) (V, bool) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	val, ok := s.m[key]
	return val, ok
}

func (s *SafeMap[K, V]) Set(key K, value V) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.m[key] = value
}

func (s *SafeMap[K, V]) Delete(key K) {
	s.mu.Lock()
	defer s.mu.Unlock()
	delete(s.m, key)
}

func (s *SafeMap[K, V]) Len() int {
	s.mu.RLock()
	defer s.mu.RUnlock()
	return len(s.m)
}

// Tests
func TestSafeMap(t *testing.T) {
	t.Run("Basic Operations", func(t *testing.T) {
		m := NewSafeMap[string, int]()

		// Set
		m.Set("a", 1)
		m.Set("b", 2)

		// Get
		val, ok := m.Get("a")
		if !ok || val != 1 {
			t.Fatalf("Expected 1, got %d, ok=%v", val, ok)
		}

		val, ok = m.Get("b")
		if !ok || val != 2 {
			t.Fatalf("Expected 2, got %d, ok=%v", val, ok)
		}

		// Get non-existent
		_, ok = m.Get("c")
		if ok {
			t.Fatal("Expected false for non-existent key")
		}

		// Delete
		m.Delete("a")
		_, ok = m.Get("a")
		if ok {
			t.Fatal("Expected false after delete")
		}

		// Length
		if m.Len() != 1 {
			t.Fatalf("Expected length 1, got %d", m.Len())
		}
	})

	t.Run("Concurrent Safety", func(t *testing.T) {
		m := NewSafeMap[int, string]()
		done := make(chan bool)

		go func() {
			for i := 0; i < 1000; i++ {
				m.Set(i, "value")
			}
			done <- true
		}()

		go func() {
			for i := 0; i < 1000; i++ {
				m.Get(i)
			}
			done <- true
		}()

		go func() {
			for i := 0; i < 1000; i++ {
				m.Delete(i)
			}
			done <- true
		}()

		<-done
		<-done
		<-done
	})
}
