package pool

import (
	"sync"
	"testing"
)

// Pool represents a worker pool.
type Pool struct {
	tasks    chan func()
	workers  int
	wg       sync.WaitGroup
	running  bool
	mu       sync.Mutex
}

// NewPool creates a new worker pool with the specified number of workers.
func NewPool(workers int) *Pool {
	p := &Pool{
		tasks:   make(chan func()),
		workers: workers,
	}
	p.start()
	return p
}

func (p *Pool) start() {
	p.mu.Lock()
	defer p.mu.Unlock()
	if p.running {
		return
	}
	p.running = true

	for i := 0; i < p.workers; i++ {
		p.wg.Add(1)
		go func() {
			defer p.wg.Done()
			for task := range p.tasks {
				task()
			}
		}()
	}
}

// Submit adds a task to the pool.
func (p *Pool) Submit(task func()) {
	p.tasks <- task
}

// Wait blocks until all submitted tasks are completed.
func (p *Pool) Wait() {
	close(p.tasks)
	p.wg.Wait()
}

// --- Tests ---

func TestPool(t *testing.T) {
	p := NewPool(4)
	var wg sync.WaitGroup
	results := make([]int, 10)

	for i := 0; i < 10; i++ {
		wg.Add(1)
		p.Submit(func(idx int) {
			defer wg.Done()
			results[idx] = idx * 2
		}(i))
	}

	wg.Wait()
	p.Wait()

	for i := 0; i < 10; i++ {
		if results[i] != i*2 {
			t.Errorf("Expected %d, got %d", i*2, results[i])
		}
	}
}

func TestPoolZeroWorkers(t *testing.T) {
	p := NewPool(0)
	done := make(chan bool)

	p.Submit(func() {
		done <- true
	})

	select {
	case <-done:
		t.Error("Task should not have executed with 0 workers")
	case <-time.After(100 * time.Millisecond):
		// Expected behavior: task stuck
	}

	// Cleanup
	p.Wait()
}

func TestPoolConcurrentSubmission(t *testing.T) {
	p := NewPool(2)
	var mu sync.Mutex
	count := 0

	for i := 0; i < 100; i++ {
		p.Submit(func() {
			mu.Lock()
			count++
			mu.Unlock()
		})
	}

	p.Wait()
	if count != 100 {
		t.Errorf("Expected 100, got %d", count)
	}
}
