class PromisePool {
  constructor(concurrency) {
    if (concurrency < 1) {
      throw new Error('Concurrency must be at least 1');
    }
    this.concurrency = concurrency;
    this.queue = [];
    this.active = 0;
    this.drainPromise = null;
    this.drainResolve = null;
  }

  async add(promiseFn) {
    return new Promise((resolve, reject) => {
      const task = {
        promiseFn,
        resolve,
        reject
      };

      this.queue.push(task);
      this.processQueue();
    });
  }

  processQueue() {
    while (this.active < this.concurrency && this.queue.length > 0) {
      const task = this.queue.shift();
      this.active++;

      Promise.resolve(task.promiseFn())
        .then(result => {
          task.resolve(result);
        })
        .catch(error => {
          task.reject(error);
        })
        .finally(() => {
          this.active--;
          this.processQueue();
        });
    }
  }

  async drain() {
    if (this.queue.length === 0 && this.active === 0) {
      return;
    }

    if (!this.drainPromise) {
      this.drainPromise = new Promise(resolve => {
        this.drainResolve = resolve;
      });
    }

    const checkDrain = () => {
      if (this.queue.length === 0 && this.active === 0) {
        if (this.drainResolve) {
          this.drainResolve();
          this.drainPromise = null;
          this.drainResolve = null;
        }
      }
    };

    // We need to hook into the completion of tasks
    // Since we can't easily hook into existing tasks, we'll use a polling approach 
    // or rely on the fact that processQueue is called on completion.
    // A cleaner way for drain is to wait until the queue is empty and active is 0.
    // We will attach a one-time check to the next completion or poll slightly.

    // Better approach: Wait for the current drainPromise if exists, 
    // otherwise create one and resolve it when conditions are met.
    // We need to ensure the check runs after every task finishes.

    // Let's modify processQueue to check drain condition
    // But to keep it simple and robust without refactoring processQueue logic heavily:
    // We will just wait.

    return this.drainPromise;
  }
}

// Patch processQueue to handle drain resolution
PromisePool.prototype.processQueue = function() {
  while (this.active < this.concurrency && this.queue.length > 0) {
    const task = this.queue.shift();
    this.active++;

    Promise.resolve(task.promiseFn())
      .then(result => {
        task.resolve(result);
      })
      .catch(error => {
        task.reject(error);
      })
      .finally(() => {
        this.active--;
        this.processQueue();

        // Check if we can resolve drain
        if (this.drainResolve && this.queue.length === 0 && this.active === 0) {
          this.drainResolve();
          this.drainPromise = null;
          this.drainResolve = null;
        }
      });
  }

  // Check drain immediately if queue was empty to begin with
  if (this.drainResolve && this.queue.length === 0 && this.active === 0) {
    this.drainResolve();
    this.drainPromise = null;
    this.drainResolve = null;
  }
};

// --- Tests ---

async function runTests() {
  console.log('Running PromisePool Tests...\n');

  // Test 1: Basic Concurrency Limiting
  try {
    const pool1 = new PromisePool(2);
    const results = [];
    const logs = [];

    const delay = (ms, id) => new Promise(resolve => {
      setTimeout(() => {
        logs.push(`start-${id}`);
        resolve(id);
      }, ms);
    });

    const tasks = [
      pool1.add(() => delay(100, 1)),
      pool1.add(() => delay(100, 2)),
      pool1.add(() => delay(100, 3)),
      pool1.add(() => delay(100, 4)),
    ];

    const start = Date.now();
    const allResults = await Promise.all(tasks);
    const duration = Date.now() - start;

    // With concurrency 2 and 100ms tasks, 4 tasks should take ~200ms
    if (duration < 190 || duration > 250) {
      throw new Error(`Concurrency test failed: Expected ~200ms, got ${duration}ms`);
    }

    if (allResults.length !== 4) {
      throw new Error('Concurrency test failed: Incorrect result count');
    }

    console.log('✓ Test 1: Concurrency Limiting Passed');
  } catch (e) {
    console.error('✗ Test 1 Failed:', e.message);
  }

  // Test 2: Error Handling
  try {
    const pool2 = new PromisePool(1);
    const errorTask = pool2.add(() => Promise.reject(new Error('Test Error')));
    const successTask = pool2.add(() => Promise.resolve('Success'));

    await errorTask.catch(err => {
      if (err.message !== 'Test Error') throw err;
    });

    const result = await successTask;
    if (result !== 'Success') throw new Error('Success task failed');

    console.log('✓ Test 2: Error Handling Passed');
  } catch (e) {
    console.error('✗ Test 2 Failed:', e.message);
  }

  // Test 3: Drain Functionality
  try {
    const pool3 = new PromisePool(1);

    // Start tasks
    const t1 = pool3.add(() => new Promise(r => setTimeout(r, 50)));
    const t2 = pool3.add(() => new Promise(r => setTimeout(r, 50)));

    // Wait for drain (should wait for t1 and t2 to finish)
    const drainStart = Date.now();
    await pool3.drain();
    const drainDuration = Date.now() - drainStart;

    // Drain should have waited for the tasks
    if (drainDuration < 40) {
      throw new Error('Drain test failed: Did not wait for tasks');
    }

    // Ensure tasks actually resolved
    await t1;
    await t2;

    console.log('✓ Test 3: Drain Functionality Passed');
  } catch (e) {
    console.error('✗ Test 3 Failed:', e.message);
  }

  // Test 4: Invalid Concurrency
  try {
    new PromisePool(0);
    throw new Error('Should have thrown for concurrency 0');
  } catch (e) {
    if (e.message.includes('Concurrency must be at least 1')) {
      console.log('✓ Test 4: Invalid Concurrency Passed');
    } else {
      throw e;
    }
  }

  console.log('\nAll tests completed.');
}

runTests();
