fn binary_search<T: Ord>(slice: &[T], target: &T) -> Option<usize> {
    let mut left = 0;
    let mut right = slice.len();

    while left < right {
        let mid = left + (right - left) / 2;
        match slice[mid].cmp(target) {
            std::cmp::Ordering::Less => left = mid + 1,
            std::cmp::Ordering::Greater => right = mid,
            std::cmp::Ordering::Equal => return Some(mid),
        }
    }
    None
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_found_in_middle() {
        let data = [1, 3, 5, 7, 9];
        assert_eq!(binary_search(&data, &5), Some(2));
    }

    #[test]
    fn test_found_at_start() {
        let data = [1, 3, 5, 7, 9];
        assert_eq!(binary_search(&data, &1), Some(0));
    }

    #[test]
    fn test_found_at_end() {
        let data = [1, 3, 5, 7, 9];
        assert_eq!(binary_search(&data, &9), Some(4));
    }

    #[test]
    fn test_not_found() {
        let data = [1, 3, 5, 7, 9];
        assert_eq!(binary_search(&data, &4), None);
    }

    #[test]
