fn fibonacci(n: u64) -> u64 {
    match n {
        0 => 0,
        1 => 1,
        _ => {
            let mut a = 0u64;
            let mut b = 1u64;
            for _ in 2..=n {
                let next = a.wrapping_add(b);
                a = b;
                b = next;
            }
            b
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_fibonacci_base_cases() {
        assert_eq!(fibonacci(0), 0);
        assert_eq!(fibonacci(1), 1);
        assert_eq!(fibonacci(2), 1);
        assert_eq!(fibonacci(3), 2);
        assert_eq!(fibonacci(4), 3);
        assert_eq!(fibonacci(5), 5);
    }

    #[test]
    fn test_fibonacci_larger_values() {
        assert_eq!(fibonacci(10), 55);
        assert_eq!(fibonacci(20), 6765);
        assert_eq!(fibonacci(30), 832040);
    }

    #[test]
    fn test_fibonacci_overflow_behavior() {
        // u64 max is 18,446,744,073,709,551,615
        // Fibonacci(93) is the largest that fits in u64
        // Fibonacci(94) overflows. Using wrapping_add handles this gracefully.
        let fib_93 = fibonacci(93);
        let fib_94 = fibonacci(94);
        // Verify that 94 is not equal to 93 (overflow occurred)
        assert_ne!(fib_93, fib_94);
    }
}
